$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$seedDir = Join-Path $root 'seed'

$updates = @{
  study_exam = @{
    E02 = '同一门课的资料常常有三个版本：同学整理的免费版、平台上的低价包、老师团队出的正版包。免费版适合补缺，但来源混杂，错题和旧题混在一起，复习到后面会浪费核对时间。低价包看起来全，问题是没有更新记录，也不知道哪些题已经不考。正版包贵一些，真正值钱的是三件事：和本学期进度同步，题目有解析，遇到争议能找到答疑入口。' + "`n`n" + '买不买正版，不该只看价格。先看这门课占多少学分、考试是否闭卷、自己有没有足够时间筛资料。轻量选修课，免费资料够用；核心课或期末占比高的课，资料的准确性比省钱更重要。资料不是越多越好，而是越少返工越好。还有一种情况更适合买可靠版本：老师每年都会微调重点，旧资料表面相似，实际会把你带到岔路。' + "`n`n" + '最稳的做法是先用免费资料试一周，发现目录对不上、答案争议多，再补更可靠的版本。花钱买的不是“上岸捷径”，只是减少信息噪声。真正要避免的是重复购买：讲义、题库和答疑三项里，缺哪项补哪项，不要把同一套内容换个封面买两遍。'
    E03 = '复习最容易犯的错，是打开第一页笔记就开始背。这样看起来很努力，实际是在把所有内容平均用力。更有效的入口是目录：先把整门课拆成几章，每章下面列出核心概念、典型题型和老师反复强调的例子。目录一旦变成地图，你就知道哪里该深挖，哪里只需要扫一遍。' + "`n`n" + '第一轮不背，专门画结构。每章用十分钟写出“这一章解决什么问题、和上一章有什么关系、最可能怎么考”。第二轮再做题，把错题标回目录里，而不是散落在不同本子上。第三轮只看高频错点和空白点，把已经稳定掌握的部分从清单里划掉。这个过程会很慢，但慢的是前面，后面会越来越快。' + "`n`n" + '判断复习是否真的有效，有一个简单标准：合上资料后，能不能从目录复述出整门课的骨架。能复述，说明知识之间已经接上；只能背出零散定义，说明还停在材料表面。最后一天不要再扩内容，只查目录上的空洞。空洞补上，分数才会稳定。'
    E04 = '课堂笔记别等到期末再救。下课后的三分钟最关键：第一行写今天的主题，第二行写老师反复说的例子，第三行写自己没听懂的地方。原文不用抄满，关键词够用。晚上再把第三行的问题补掉，整页笔记就活了。长期坚持，期末翻到任何一页，都知道它为什么存在，也知道该从哪一行重新接上。'
    E06 = '错题本不一定要电子化。纸质本的好处是慢：抄题会逼你重新看条件，手写解析会暴露自己到底卡在哪一步。拍照收藏很快，但快到经常再也不看。我的做法是只收三类题：反复错的、思路新鲜的、能串起一章知识的。数量少，翻起来才有用。稳一点，不丢人。真正要紧的是下次能看懂，而不是今天整理得多漂亮。'
    E07 = '一份像样的实验报告，重点不在步骤写了多少，而在它能不能回答三个问题：你原本想验证什么，实际测到了什么，偏差从哪里来。很多报告把仪器型号和操作流程写得很长，却在结果分析里只放一句“误差较小”。这句话最没信息量，因为所有真正有价值的部分都藏在误差里。' + "`n`n" + '写报告时，先把假设放在前面。比如某个变量升高，结果应该怎样变化；如果结果反着来，可能是测量方法错了，也可能是模型本身不适合。数据表不要只贴原始数，至少画一张趋势图，让读的人一眼看见拐点。讨论部分不要急着找借口，先列可复现的原因：读数间隔、样本数量、环境变化、仪器精度。能复测的写复测结果，不能复测的写清限制。' + "`n`n" + '结论最好短，但要硬。它不是“本实验加深了理解”，而是“在这个范围内，变量 A 对结果 B 的影响更明显”。写到这一步，报告才像一次真实观察，而不是一次格式作业。最后检查一遍图表标题和单位，很多低级扣分都藏在这里。'
    E08 = '公开课列表太长，别一口气收藏二十门。先分三类：入门课，用来补基本概念；案例课，看别人怎么把概念用起来；复盘课，专门听老师总结常见错误。每类先挑一门，听完第一讲就决定留不留。收藏夹不是仓库，越满越不想打开。留下三门认真跟，比存一百个链接更像开始。'
    E09 = '复习计划别排满一整页，今晚只定三件事：背完一章概念，做完一套例题，整理十道错题。每件事都要能打勾，不能写“多看看”“再巩固”。时间到了就停，不临时加码。计划越小，越容易开始；开始之后，第二天才有底气继续排。先做成一晚，再谈完整周期。'
    E10 = '复习方法常被说成选择题：刷题还是背书，做笔记还是看视频。其实它们解决的是不同问题。刷题适合检验漏洞，尤其适合理科和有固定题型的课程；背书适合建立基本语料，概念课和需要准确表述的内容绕不开；讲给别人听，则适合检查自己是否真的懂了，因为讲不顺的地方，往往就是知识没有接上的地方。' + "`n`n" + '比较这三种方法，要看科目目标。公式推导类课程，先刷基础题，再用错题倒查概念；理论类课程，先背关键词，再用自己的话重组段落；案例类课程，最有效的是把案例讲成一条因果链。不要在一种方法上赌到底，复习到后半段，三种方法最好轮换。只刷题会漏表达，只背书会漏应用，只看视频最容易产生已经懂了的错觉。' + "`n`n" + '一个简单安排是：白天刷题找漏洞，晚上背概念补语言，第二天早上用五分钟讲一遍。能讲出来的留着，讲不出的回炉。这样比只看资料更慢，但更稳。到考前最后两天，就不要再换方法，只保留最能暴露问题的那一种。'
    E11 = '小组作业最怕“你负责资料，我负责 PPT”这种分工，看起来平均，最后谁都说不清自己该交什么。分工表要写三列：交付物是什么，什么时候交，怎么判断合格。比如“找资料”要改成“整理三篇可引用材料，每篇写 80 字摘要”；“做 PPT”要改成“周五前给出十页初稿，含图表占位”。' + "`n`n" + '还要提前约定合并方式。每个人的内容风格不同，如果最后一天才拼，格式和逻辑都会散。比较稳的做法是先定目录，再分段写，最后由一个人统一口径。讨论群里少发“大家看看”，多发“这两个版本选哪个”。每次讨论都留下结论，不然下一次还会从同一个问题重新开始。' + "`n`n" + '分工不是为了算账，而是为了让合作可验收。写清楚，尴尬会少很多。真正需要避免的是沉默成本：有人没交、有人不会、有人临时改方向，都应该尽早暴露。小组作业不是看谁最后熬夜补洞，而是看一开始有没有把洞标出来。'
    E12 = '本周试了五个小技巧：早八前只看一页复习清单，不碰消息；课后马上补三行笔记；背词只背十分钟，到点就停；错题先标原因，不急着重做；睡前把第二天第一件事写在纸上。没有哪个神奇，但胜在轻。挑一个今天就用，比收藏十篇方法文更有用。用三天再决定留不留，别第一天就把习惯表填满。'
    P07 = '自习座位别只看哪里安静。图书馆适合长时间阅读，自习室适合刷题，空教室适合小声背诵。选位置也有小技巧：离门太近容易被打断，靠窗容易分心，插座旁边最抢手但人也最多。先想清今天要做什么，再选地方，效率会高很多。实在选不到理想座位，就把任务切小一点，别让找位置消耗半小时。'
    P08 = '错题本要不要重写，取决于你错在哪里。计算粗心的题，只标提醒就够；概念混淆的题，要把相关定义写在旁边；思路完全断掉的题，才需要完整重写。所有错题都重抄一遍，看起来很整齐，但容易把时间花在排版上。错题本不是作品集，是给下一次复习看的工具。能让你少错一次，就已经合格。'
  }
  social_hot = @{
    H02 = '很多人把社团展演理解成“节目排出来就行”，真正影响体验的却是细节。灯光太亮，舞台层次会被抹平；音量忽大忽小，观众很快出戏；主持串词如果只负责报幕，节目之间就会断成一截一截。做得讲究一点，不是为了显得高级，而是让台下的人愿意多停留十分钟。' + "`n`n" + '预算有限时，最该优先的是动线和节奏。入口要一眼看见签到位置，节目单最好能扫码查看，观众离场时不要和候场人员撞在一起。主持人的任务也不是讲笑话，而是在每个节目之前给一个进入情绪的理由。哪怕设备普通，只要节奏顺，展演就不会散。' + "`n`n" + '这类活动的价值不只在当天。一次认真完成的展演，会留下照片、视频、流程表和复盘记录，下一届接手时不必从零开始。品质感不是花大钱堆出来的，而是每个环节都有人负责。复盘时把最卡的三处写下来，比单纯夸“很成功”更有用。'
    H03 = '热梗最开始往往只是群聊里的一个表情或一句改写，真正变成校园议题，要经历几次转场。第一次是从熟人群转到公开平台，语境被稀释，玩笑开始被不同的人重新解释。第二次是从线上转到线下，海报、活动标题、课堂讨论都会借用它，原本轻松的表达就带上了观点。第三次是反向传播：有人开始解释这个梗“到底什么意思”，它就从玩笑变成了可讨论对象。' + "`n`n" + '理解这个过程，比判断一个梗好不好笑更重要。很多误会都发生在语境迁移时：A 群里默认大家知道背景，B 平台上的路人却只看到一句话。传播越快，省略的上下文越多。于是同一个表达，有人觉得亲切，有人觉得冒犯，有人完全看不懂。' + "`n`n" + '下次看到一个校园热词突然刷屏，不妨先问三件事：它从哪里来，谁在使用它，被谁误解了。热点不是凭空出现的，它只是把原本分散的情绪集中照亮了一下。先补上下文，再决定要不要跟着转发。'
    H04 = '本周校园里被转发最多的五类话题：自习室占座规则更新，社团招新二轮补录，食堂新窗口试营业，运动会志愿者排班，毕业季旧物交换。每个话题背后都不复杂，复杂的是大家的感受不一样。先知道发生了什么，再决定要不要参与讨论。看热闹也可以慢半拍，别被第一张截图带着跑。'
    H05 = '新社团的体验日刚开放报名，我第一批填了表。项目不算成熟，流程还在试运行，但胜在空间很大：可以参与规则设计，也能直接认识第一批成员。老牌社团稳定，新社团更像一张空白纸，适合喜欢尝鲜的人。唯一要有心理准备的是，前几次活动可能会乱一点，需要自己多问一句安排。'
    H06 = '老牌社团的固定活动年年差不多，却一直有人参加。原因很简单：时间固定，地点固定，流程也固定。新成员知道自己会经历什么，老成员知道哪里需要帮忙。它不一定最刺激，但很可靠。对只想放松一下的人来说，确定感本身就是吸引力。稳定的活动也更容易带朋友来，不用解释太多。'
    H07 = '志愿活动最容易乱在排班，而不是现场。表格里如果只写姓名和时间，到了现场一定会有人问“我具体做什么”。一张合格的排班表至少有四列：岗位、时段、负责人、交接说明。签到岗要知道物料在哪里，秩序岗要知道什么时候引导排队，机动岗要知道谁有权临时调人。' + "`n`n" + '替补也必须提前写进表里。很多活动默认“临时再说”，结果一旦有人迟到，所有人都在群里找人。更稳的做法是每个关键岗位配一个备用人，并写清替补触发条件：迟到十分钟、临时离场、现场人流超过预估，都应该自动换人。' + "`n`n" + '活动结束后还要留一份复盘，不写情绪，只写事实：哪个时段人最多，哪个岗位任务不清，哪些物料多了或少了。下一次活动如果能少问一半问题，这次排班才算真正有效。复盘表越具体，后来的人越省力。'
    H08 = '食堂新窗口投票开了，评论区比菜单还热闹。有人关心排队时间，有人关心价格，有人只想要口味稳定。先别急着站队，把高赞评论按这三类分一下，就能看出大家真正想解决什么。投票不只是选吃什么，也是一次小型需求调查。看懂关注点，再投那一票，会比跟风更有意义。'
    H09 = '今晚有三项活动：露天电影、主题讲座、操场夜跑。想轻松就去电影，想带点收获就去讲座，想活动身体就去夜跑。每个选择都不错，别在群里问半小时。看天气、看距离、看自己现在的状态，选一个就出门。活动最大的损耗，经常发生在犹豫里。去不成也没关系，至少把今晚留给一件确定的事。'
    H10 = '社团招新常见两种方案：一种把摊位做得热闹，海报醒目、小游戏多、奖品摆满；另一种把体验做深，安排十分钟真实任务，让新同学提前感受社团平时怎么运转。前者吸引路过的人，后者筛出真正愿意留下的人，不能简单说谁更好。' + "`n`n" + '如果目标是扩大知名度，热闹型更有效。它降低参与门槛，让陌生人愿意停下脚步，适合刚恢复活动或缺少曝光的社团。问题是报名表会很漂亮，实际到场率可能不高。体验型相反，现场看起来没那么炸，但参与者更清楚自己要加入什么，后续流失少。' + "`n`n" + '比较稳的组合是先热闹引流，再用小任务做二次确认。第一天让人知道你，第二天让人试着做一件真实的事。招新不是收集联系方式，而是让双方都少一点误会。最后复盘别只看报名数，还要看两周后的留存。'
    H11 = '校园通知截图最容易被转发，也最容易过期。核验时先看来源：是否来自学院、部门或活动主页，而不是二次截图。再看时间：很多通知隔了几天，地点和截止时间已经改过。最后找原文链接，截图里少掉的备注，往往才是关键。' + "`n`n" + '如果找不到原文，不要急着继续转发。可以在群里补一句“来源待确认”，或者只把它当作提醒去查官网。截图天然会丢上下文，尤其是报名条件、人数限制、材料要求这些细节。少转一次不确定的信息，比事后解释强。' + "`n`n" + '信息素养不是怀疑一切，而是知道什么需要多看一眼。越是和大家相关的通知，越值得慢半拍。遇到标题很急、措辞很满的截图，更要先停一下：真正重要的信息，通常经得起你多查一分钟。'
    H12 = '今天群里最热的三条：自习室占座提醒又被顶上来，社团二轮招新名单更新，食堂新窗口试吃排了长队。三条看似不相关，其实都和同一件事有关：校园里的公共资源怎么分配。先看发生了什么，再看大家为什么在意。热点不一定很大，和每个人的日常有关，就足够被反复讨论。'
    P13 = '今天校园里大家在聊的事不复杂：自习室座位调整，社团开放日排期，食堂新窗口试营业。每条都和日常有关，也都不需要马上表态。先知道发生了什么，再决定要不要点进去看细节。信息流里的很多热点，都是从这种小变化开始的。看见转发很多，也可以先慢一步看看。'
    P14 = '社团开放日别只在摊位前扫二维码。先看活动时间是否稳定，再问平时需要投入多少精力，最后体验一个最小任务，比如试做海报、试排节目、试打一场友谊赛。真正适合自己的社团，不是宣传语最热闹的那个，而是你愿意下周继续来的那个。多问一句日常安排，比只看海报可靠。'
  }
}

$append = @{
  study_exam = @{
    E09 = ' 做完以后顺手记录实际用时，明天就能排得更准。'
  }
  social_hot = @{
    H02 = ' 如果时间允许，还可以提前做一次空场走位：主持人从哪里上台，观众从哪里进出，设备线藏在哪里，全部走一遍，正式演出时就少一半慌乱。'
    H07 = ' 如果现场有临时变化，也不要只在群里喊一句，最好同步改表，让后来接班的人看到同一份最新版本。'
    H10 = ' 还要注意别把所有资源都花在第一天，真正决定留下来的，往往是第二次活动有没有人继续跟进安排。'
    H11 = ' 核验完成后再转发，也尽量附上原链接，让后来看到的人可以自己判断，而不是只依赖你的截图。遇到多个版本同时流传时，把差异列出来，比急着给结论更稳。'
  }
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
foreach ($domain in $updates.Keys) {
  $path = Join-Path $seedDir "$domain.json"
  $j = Get-Content -Raw -Encoding UTF8 $path | ConvertFrom-Json
  $map = $updates[$domain]
  foreach ($section in @('interest','probes')) {
    foreach ($it in @($j.$section)) {
      if ($map.ContainsKey($it.content_id)) {
        $it.body = $map[$it.content_id]
        if ($append.ContainsKey($domain) -and $append[$domain].ContainsKey($it.content_id)) {
          $it.body += $append[$domain][$it.content_id]
        }
      }
    }
  }
  [System.IO.File]::WriteAllText($path, ($j | ConvertTo-Json -Depth 12), $utf8)
}

Write-Host 'student domain bodies updated'
